//
//  Pocket SDR - Acquisition Accelerator Plugin for Axera NPU (AXCL).
//
//  The parallel code search is executed on an Axera AX650/AX8850 NPU of a PCIe
//  card (M5Stack LLM-8850 etc.) by axmodels generated by gen_axcl_acq.py from
//  the ONNX model of a four-step DFT (shared DFT: the DFT of the IF samples of
//  a window by the host (FFTW), the Doppler bins of a chunk of Kc bins spaced
//  by fs / M as the shifts of the DFT on the NPU, the chunks by the code DFT
//  rolled by the host):
//
//    acq_M<M>_K<Kc>_R<R>_hs[_w<nw>].axmodel: inputs xr, xi [nw][M], cr, ci [M]
//        (int8, X of nw windows and C in the natural order [k2][k1] of
//        X[A*k2+k1]), Pa (float, accumulated power), output P = Pa + sum of
//        |corr|^2 / 64 of the windows [k][p1][p2] (float, 16-bit quantized
//        inside)
//
//  acq_M<M>_K<Kc>_R<R>_hs[_w<nw>]_red.axmodel: outputs Pmax, Psum, Parg (max,
//        sum and index of max of P over p2) in addition, for the search reduced
//        to the peak (search_code_peak(), R * B = nout, only the reduced
//        outputs and the powers at the peak in the neighbor bins copied back)
//
//  The model of the shortest estimated time (inferences of chunks x groups of
//  nw windows by the execution time measured at the load, and the copy of the
//  outputs) is selected. All models in the directory are loaded at the
//  initialization.
//
//  The IF samples of the windows and the rolled code DFTs of the chunks are
//  copied to the device once per call (the PCIe link of the card is 5 GT/s x1,
//  about 370 MB/s with 0.12 ms latency per copy), the windows are integrated
//  on the device by the accumulation input and the powers of the chunks are
//  copied back once per call.
//
//  options: [model=dir]
//           model=dir: directory of axmodels (default: $SDR_ACC_AXCL_MODEL or
//                  <plugin dir>/axcl)
//
//  Author:
//  T.SUZUKI
//
//  History:
//  2026-10-23  1.0  new
//
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>
#include <time.h>
#include <dlfcn.h>
#include <dirent.h>
#include <string>
#include <vector>
#include <map>
#include <memory>
#include <mutex>
#include <thread>
#include <atomic>
#include <algorithm>
#include <array>
#include <fftw3.h>
#include <axcl.h>
#include "sdr_acc.h"

#define PI         3.1415926535897932
#define SX         32.0     // RMS of IF sample DFT inputs (int8)
#define SC         127.0    // max of code DFT inputs (int8)
#define NTHREAD    4        // threads of host preparation
#define AXCL_CONF  "/usr/bin/axcl/axcl.json"
#define BW_D2H     370e6    // device to host copy rate (bytes/s)

// axmodel ---------------------------------------------------------------------
struct amodel_t {
    uint64_t id = 0, ctx = 0;
    axclrtEngineIOInfo info = NULL;
    axclrtEngineIO io = NULL;
    int M = 0, Kc = 0, R = 0, A = 0, B = 0, nw = 1;
    int idx[5];                         // input indices of xr, xi, cr, ci, Pa
    int odx[4] = {-1, -1, -1, -1};      // output indices of P, Pmax, Psum, Parg
    int red = 0, arg_bytes = 0;         // reduced outputs, bytes of Parg element
    uint64_t size_out = 0;              // bytes of output P
    double t_exec = 0.0;                // execution time measured at load (s)
};

static int dev_id = -1;
static axclrtContext dctx = NULL;
static std::map<std::string, std::unique_ptr<amodel_t>> amodels;
static std::string model_dir;
static std::vector<std::array<int, 5>> mfiles; // axmodels in model_dir (M, Kc, R, nw, red)
static std::mutex call_mtx;

// device buffers (grown as required) ------------------------------------------
struct dbuf_t {
    void *p = NULL;
    size_t size = 0;
    int alloc(size_t n) {
        if (n <= size) return 1;
        if (p) axclrtFree(p);
        p = NULL; size = 0;
        if (axclrtMalloc(&p, n, AXCL_MEM_MALLOC_NORMAL_ONLY)) return 0;
        size = n;
        return 1;
    }
    void free_() { if (p) axclrtFree(p); p = NULL; size = 0; }
};
static dbuf_t d_in, d_acc[2], d_zero, d_out, d_red, d_redt; // inputs, accumulation,
                                // zeros, outputs, reduced outputs (and scratch)

// current time (s) ------------------------------------------------------------
static double now(void)
{
    struct timespec t;
    clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec * 1e-9;
}

// load axmodel for (M, Kc, R, nw) -----------------------------------------------
static amodel_t *get_model(int M, int Kc, int R, int nw, int red)
{
    char key[64], w[16] = "";
    if (nw > 1) snprintf(w, sizeof(w), "_w%d", nw);
    snprintf(key, sizeof(key), "acq_M%d_K%d_R%d_hs%s%s", M, Kc, R, w, red ? "_red" : "");
    auto it = amodels.find(key);
    if (it != amodels.end()) return it->second.get();
    std::string file = model_dir + "/" + key + ".axmodel";
    std::unique_ptr<amodel_t> m(new amodel_t);
    amodels[key] = nullptr;
    if (axclrtEngineLoadFromFile(file.c_str(), &m->id) ||
        axclrtEngineCreateContext(m->id, &m->ctx) ||
        axclrtEngineGetIOInfo(m->id, &m->info)) {
        fprintf(stderr, "sdr_acc_axcl: model load error %s\n", file.c_str());
        return NULL;
    }
    const char *names[5] = {"xr", "xi", "cr", "ci", "Pa"};
    uint32_t nin = axclrtEngineGetNumInputs(m->info), nout = axclrtEngineGetNumOutputs(m->info);
    if (nin != 5 || nout != (red ? 4u : 1u)) {
        fprintf(stderr, "sdr_acc_axcl: model I/O error %s\n", file.c_str());
        return NULL;
    }
    const char *onames[4] = {"P", "Pmax", "Psum", "Parg"};
    for (uint32_t j = 0; j < nout; j++) {
        for (int i = 0; i < 4; i++) {
            if (!strcmp(axclrtEngineGetOutputNameByIndex(m->info, j), onames[i])) m->odx[i] = j;
        }
    }
    if (m->odx[0] < 0 || (red && (m->odx[1] < 0 || m->odx[2] < 0 || m->odx[3] < 0))) {
        fprintf(stderr, "sdr_acc_axcl: model outputs error %s\n", file.c_str());
        return NULL;
    }
    for (int i = 0; i < 5; i++) {
        m->idx[i] = -1;
        for (uint32_t j = 0; j < nin; j++) {
            if (!strcmp(axclrtEngineGetInputNameByIndex(m->info, j), names[i])) m->idx[i] = j;
        }
        if (m->idx[i] < 0) {
            fprintf(stderr, "sdr_acc_axcl: no input %s %s\n", names[i], file.c_str());
            return NULL;
        }
    }
    axclrtEngineIODims dims;
    if (axclrtEngineGetInputDims(m->info, 0, m->idx[0], &dims) || dims.dimCount != 4) {
        return NULL;
    }
    m->M = M; m->Kc = Kc; m->R = R; m->nw = nw;
    m->B = dims.dims[1] / nw; m->A = dims.dims[3]; // X [1][nw*B][1][A]
    m->size_out = axclrtEngineGetOutputSizeByIndex(m->info, 0, m->odx[0]);
    if (red) {
        m->red = 1;
        m->arg_bytes = (int)(axclrtEngineGetOutputSizeByIndex(m->info, 0, m->odx[3]) / ((uint64_t)Kc * R));
        if ((m->arg_bytes != 4 && m->arg_bytes != 8) ||
            axclrtEngineGetOutputSizeByIndex(m->info, 0, m->odx[1]) != (uint64_t)Kc * R * 4 ||
            axclrtEngineGetOutputSizeByIndex(m->info, 0, m->odx[2]) != (uint64_t)Kc * R * 4) {
            fprintf(stderr, "sdr_acc_axcl: model reduced outputs error %s\n", file.c_str());
            return NULL;
        }
    }
    if (m->A * m->B != M ||
        axclrtEngineGetInputSizeByIndex(m->info, 0, m->idx[0]) != (uint64_t)M * nw ||
        axclrtEngineGetInputSizeByIndex(m->info, 0, m->idx[2]) != (uint64_t)M ||
        axclrtEngineGetInputSizeByIndex(m->info, 0, m->idx[4]) != m->size_out ||
        m->size_out != (uint64_t)Kc * R * m->B * sizeof(float)) {
        fprintf(stderr, "sdr_acc_axcl: model shape error %s\n", file.c_str());
        return NULL;
    }
    if (axclrtEngineCreateIO(m->info, &m->io)) return NULL;

    // execution time measured by inputs of zeros (median of 3)
    std::vector<void *> bufs;
    for (uint32_t j = 0; j < nin + nout; j++) {
        uint64_t n = j < nin ? axclrtEngineGetInputSizeByIndex(m->info, 0, j) :
            axclrtEngineGetOutputSizeByIndex(m->info, 0, j - nin);
        void *b = NULL;
        if (axclrtMalloc(&b, n, AXCL_MEM_MALLOC_NORMAL_ONLY) || axclrtMemset(b, 0, n) ||
            (j < nin ? axclrtEngineSetInputBufferByIndex(m->io, j, b, n) :
             axclrtEngineSetOutputBufferByIndex(m->io, j - nin, b, n))) {
            for (auto q : bufs) axclrtFree(q);
            return NULL;
        }
        bufs.push_back(b);
    }
    double ts[3];
    for (int i = 0; i < 4; i++) {
        double t0 = now();
        if (axclrtEngineExecute(m->id, m->ctx, 0, m->io)) break;
        if (i > 0) ts[i - 1] = now() - t0;
    }
    std::sort(ts, ts + 3);
    m->t_exec = ts[1];
    for (auto q : bufs) axclrtFree(q);
    if (getenv("SDR_ACC_AXCL_DEBUG")) {
        fprintf(stderr, "sdr_acc_axcl: %s exec %.3f ms\n", key, m->t_exec * 1e3);
    }
    amodel_t *p = m.get();
    amodels[key] = std::move(m);
    return p;
}

// carrier table exp(-j*2*pi*f*n) (n = 0..M-1) -----------------------------
static void carr_table(double f, int M, int B, float *tab)
{
    double dr = cos(-2.0 * PI * f), di = sin(-2.0 * PI * f);
    for (int n1 = 0; n1 < M / B; n1++) { // renormalized every row
        double ph = -2.0 * PI * fmod(f * B * n1, 1.0), cr = cos(ph), ci = sin(ph);
        for (int n2 = 0; n2 < B; n2++) {
            int n = B * n1 + n2;
            tab[2*n] = (float)cr; tab[2*n+1] = (float)ci;
            double t = cr * dr - ci * di;
            ci = cr * di + ci * dr; cr = t;
        }
    }
}

// FFTW plans by M (by call_mtx) -----------------------------------------------
static std::map<int, fftwf_plan> fplans;

static fftwf_plan get_plan(int M)
{
    auto it = fplans.find(M);
    if (it != fplans.end()) return it->second;
    fftwf_complex *a = fftwf_alloc_complex(M), *b = fftwf_alloc_complex(M);
    fftwf_plan p = fftwf_plan_dft_1d(M, a, b, FFTW_FORWARD, FFTW_ESTIMATE);
    fftwf_free(a); fftwf_free(b);
    return fplans[M] = p;
}

static inline int8_t quant8(float v)
{
    v = roundf(v);
    return (int8_t)(v < -128.f ? -128.f : (v > 127.f ? 127.f : v));
}

// quantized unitary DFT of IF samples of a window wiped by a carrier table ----
static void prep_window(int M, const int8_t *__restrict x, const float *__restrict tab,
    double sx, fftwf_complex *in, fftwf_complex *out, int8_t *xr, int8_t *xi)
{
    for (int n = 0; n < M; n++) {
        float re = x[2*n], im = x[2*n+1], cr = tab[2*n], ci = tab[2*n+1];
        in[n][0] = re * cr - im * ci; in[n][1] = re * ci + im * cr;
    }
    fftwf_execute_dft(get_plan(M), in, out);
    float s = (float)(SX / sqrt((double)M) / sx);
    for (int m = 0; m < M; m++) {
        xr[m] = quant8(out[m][0] * s); xi[m] = quant8(out[m][1] * s);
    }
}

// set reduced outputs Pmax, Psum, Parg of a model to device buffer p ---------
static int set_red_outputs(const amodel_t *m, char *p)
{
    size_t nr = (size_t)m->Kc * m->R;
    return axclrtEngineSetOutputBufferByIndex(m->io, m->odx[1], p, nr * 4) ||
        axclrtEngineSetOutputBufferByIndex(m->io, m->odx[2], p + nr * 4, nr * 4) ||
        axclrtEngineSetOutputBufferByIndex(m->io, m->odx[3], p + nr * 8, nr * m->arg_bytes);
}

// parallel code search of NW windows (non-coherent integration) -------------
//   P != NULL: P[k*ldP+n] += powers, P == NULL: reduced to the peak Pk, ixk
static int search_multi(const int8_t **xs, int NW, const float *code, int M,
    double fs, const double *fc, int K, int nout, float *P, int ldP,
    float *Pk, int *ixk, sdr_acc_prof_t *prof)
{
    int peak = P == NULL;
    if (dev_id < 0 || K < 1 || NW < 1) return 0;
    std::lock_guard<std::mutex> lock(call_mtx);
    double t0 = now();

    // uniform bins spaced by fs / M (tolerance for single precision Doppler)
    for (int k = 1; k < K; k++) {
        if (fabs((fc[k] - fc[0]) * M / fs - k) > 1e-3) return 0;
    }
    // model of M with the shortest estimated time of the inferences (chunks of
    // K bins x groups of nw windows) and the copy of the outputs, R >= nout / B
    amodel_t *m = NULL;
    double tmin = 0.0;
    if (axclrtSetCurrentContext(dctx)) return 0;
    for (auto &f : mfiles) {
        if (f[0] != M) continue;
        if (peak && !f[4]) continue;
        amodel_t *mi = get_model(M, f[1], f[2], f[3], f[4]);
        if (!mi || mi->R * mi->B < nout || (peak && mi->R * mi->B != nout)) continue;
        int nc = (K + mi->Kc - 1) / mi->Kc, ng = (NW + mi->nw - 1) / mi->nw;
        double t = nc * ng * mi->t_exec + (peak ? 0.0 : nc * (double)mi->size_out / BW_D2H);
        if (!m || t < tmin) {
            m = mi;
            tmin = t;
        }
    }
    if (!m) return 0;
    int Kc = m->Kc, B = m->B, R = m->R, nch = (K + Kc - 1) / Kc;

    // model without the reduced outputs (same shape) for the groups except the
    // last of the search reduced to the peak (the reductions take 20-30% time)
    amodel_t *m0 = m;
    if (peak) {
        for (auto &f : mfiles) {
            if (f[0] == M && f[1] == Kc && f[2] == R && f[3] == m->nw && !f[4]) {
                amodel_t *mi = get_model(M, Kc, R, m->nw, 0);
                if (mi && mi->B == B) m0 = mi;
            }
        }
    }
    int nw = m->nw, ng = (NW + nw - 1) / nw; // groups of nw windows
    size_t nP = (size_t)Kc * R * B;

    // RMS of the windows and code DFT normalized by max magnitude
    std::vector<double> sx(NW, 0.0);
    double cmax = 0.0;
    for (int w = 0; w < NW; w++) {
        for (int i = 0; i < 2 * M; i++) {
            double v = xs[w][i];
            sx[w] += v * v;
        }
        sx[w] = sqrt(sx[w] / M);
        if (sx[w] <= 0.0) return 0;
    }
    for (int i = 0; i < M; i++) {
        cmax = std::max(cmax, (double)hypot(code[2*i], code[2*i+1]));
    }
    if (cmax <= 0.0) return 0;

    // host inputs: X of groups of windows [ng][2][nw][M] (windows >= NW zero),
    // code DFT twice [2][2*M] (the rolled code DFT of chunk c C[(m - s) mod M],
    // s = c * Kc, at offset M - s: |IDFT(X[m+s] C[m])| = |IDFT(X[m] C[m-s])|)
    size_t n_x = (size_t)ng * 2 * nw * M, n_in = n_x + (size_t)4 * M;
    std::vector<int8_t> h_in(n_in, 0);
    std::vector<float> tab(2 * M);
    carr_table(fc[0] / fs, M, B, tab.data());
    get_plan(M);

    std::vector<std::thread> th;
    for (int t = 0; t < NTHREAD; t++) {
        th.emplace_back([&, t]() {
            fftwf_complex *in = fftwf_alloc_complex(M), *out = fftwf_alloc_complex(M);
            for (int w = t; w < NW; w += NTHREAD) {
                int8_t *p = h_in.data() + ((size_t)(w / nw) * 2 * nw + w % nw) * M;
                prep_window(M, xs[w], tab.data(), sx[w], in, out, p, p + (size_t)nw * M);
            }
            fftwf_free(in); fftwf_free(out);
        });
    }
    {
        std::vector<int8_t> cr(M), ci(M);
        float s = (float)(SC / cmax);
        for (int i = 0; i < M; i++) {
            cr[i] = quant8(code[2*i] * s); ci[i] = quant8(code[2*i+1] * s);
        }
        int8_t *pr = h_in.data() + n_x, *pi = pr + 2 * (size_t)M;
        memcpy(pr, cr.data(), M); memcpy(pr + M, cr.data(), M);
        memcpy(pi, ci.data(), M); memcpy(pi + M, ci.data(), M);
    }
    for (auto &t : th) t.join();
    double t1 = now();

    // device buffers and copy of the inputs
    if (axclrtSetCurrentContext(dctx) ||
        !d_in.alloc(n_in) || !d_acc[0].alloc(nP * 4) || !d_acc[1].alloc(nP * 4) ||
        !d_out.alloc(nP * 4 * nch) ||
        (m->red && (!d_red.alloc((size_t)nch * Kc * R * (8 + m->arg_bytes)) ||
                    !d_redt.alloc((size_t)Kc * R * (8 + m->arg_bytes))))) {
        fprintf(stderr, "sdr_acc_axcl: device memory error\n");
        return 0;
    }
    if (d_zero.size < nP * 4) {
        if (!d_zero.alloc(nP * 4) || axclrtMemset(d_zero.p, 0, nP * 4)) return 0;
    }
    if (axclrtMemcpy(d_in.p, h_in.data(), n_in, AXCL_MEMCPY_HOST_TO_DEVICE)) {
        fprintf(stderr, "sdr_acc_axcl: memcpy error\n");
        return 0;
    }
    double t2 = now();

    // inferences of chunks x groups of windows, groups integrated on the device
    // (the last group of a chunk output to the chunk slot of d_out)
    char *din = (char *)d_in.p;
    size_t nx = (size_t)nw * M;
    for (int c = 0; c < nch; c++) {
        int sft = (int)(((long)c * Kc) % M);
        char *cr = din + n_x + (M - sft), *ci = cr + 2 * (size_t)M;
        for (int w = 0; w < ng; w++) {
            char *xw = din + (size_t)w * 2 * nx;
            void *pa = w == 0 ? d_zero.p : d_acc[(w - 1) % 2].p;
            void *po = w == ng - 1 ? (char *)d_out.p + nP * 4 * c : d_acc[w % 2].p;
            amodel_t *mw = w == ng - 1 ? m : m0;
            if (axclrtEngineSetInputBufferByIndex(mw->io, mw->idx[0], xw, nx) ||
                axclrtEngineSetInputBufferByIndex(mw->io, mw->idx[1], xw + nx, nx) ||
                axclrtEngineSetInputBufferByIndex(mw->io, mw->idx[2], cr, M) ||
                axclrtEngineSetInputBufferByIndex(mw->io, mw->idx[3], ci, M) ||
                axclrtEngineSetInputBufferByIndex(mw->io, mw->idx[4], pa, nP * 4) ||
                axclrtEngineSetOutputBufferByIndex(mw->io, mw->odx[0], po, nP * 4) ||
                (mw->red && set_red_outputs(mw, w == ng - 1 ? (char *)d_red.p +
                    (size_t)c * Kc * R * (8 + m->arg_bytes) : (char *)d_redt.p)) ||
                axclrtEngineExecute(mw->id, mw->ctx, 0, mw->io)) {
                fprintf(stderr, "sdr_acc_axcl: inference error\n");
                return 0;
            }
        }
    }
    double t3 = now();

    // copy of the outputs and P[k][n] += out[k][n] * 64 / M^2 / SX^2 / SC^2 *
    // sx^2 * cmax^2 (n = B * p1 + p2, the windows of different RMS integrated with the
    // scale of the windows: exact for the same RMS, the RMS of the windows of
    // a buffer nearly equal)
    double sxm = 0.0;
    for (int w = 0; w < NW; w++) sxm += sx[w] * sx[w] / NW;
    float sc = (float)(64.0 / ((double)M * M) / (SX * SX) / (SC * SC) * sxm * cmax * cmax);
    if (peak) { // peak of the reduced outputs of bins < K, the neighbor bins at the peak
        size_t nr = (size_t)Kc * R, nb = nr * (8 + m->arg_bytes);
        std::vector<char> h_red(nb * nch);
        if (axclrtMemcpy(h_red.data(), d_red.p, nb * nch, AXCL_MEMCPY_DEVICE_TO_HOST)) {
            fprintf(stderr, "sdr_acc_axcl: memcpy error\n");
            return 0;
        }
        double t4 = now(), sum = 0.0;
        float pmax = -1.0f;
        int kmax = 0, rmax = 0;
        for (int k = 0; k < K; k++) {
            const char *r = h_red.data() + (size_t)(k / Kc) * nb;
            const float *rm = (const float *)r + (size_t)(k % Kc) * R;
            const float *rs = (const float *)(r + nr * 4) + (size_t)(k % Kc) * R;
            for (int p1 = 0; p1 < R; p1++) {
                sum += rs[p1];
                if (rm[p1] > pmax) { pmax = rm[p1]; kmax = k; rmax = p1; }
            }
        }
        const char *ra = h_red.data() + (size_t)(kmax / Kc) * nb + nr * 8;
        size_t ia = (size_t)(kmax % Kc) * R + rmax;
        long p2 = m->arg_bytes == 8 ? (long)((const int64_t *)ra)[ia] : (long)((const int32_t *)ra)[ia];
        ixk[0] = kmax; ixk[1] = B * rmax + (int)p2;
        Pk[0] = pmax * sc;
        Pk[1] = (float)(sum / ((double)K * nout) * sc);
        for (int i = 0; i < 2; i++) { // neighbor bins
            int k = kmax + (i ? 1 : -1);
            float v = 0.0f;
            if (k >= 0 && k < K && axclrtMemcpy(&v, (char *)d_out.p + ((size_t)(k / Kc) * nP +
                (size_t)(k % Kc) * R * B + ixk[1]) * 4, 4, AXCL_MEMCPY_DEVICE_TO_HOST)) {
                return 0;
            }
            Pk[2 + i] = v * sc;
        }
        double t5 = now();
        if (getenv("SDR_ACC_AXCL_DEBUG")) {
            fprintf(stderr, "sdr_acc_axcl: M=%d Kc=%d R=%d nw=%d K=%d NW=%d nch=%d prep %.2f "
                "in %.2f exec %.2f out %.2f peak %.2f ms (peak)\n", M, Kc, R, nw, K, NW, nch,
                (t1 - t0) * 1e3, (t2 - t1) * 1e3, (t3 - t2) * 1e3, (t4 - t3) * 1e3, (t5 - t4) * 1e3);
        }
        if (prof) {
            prof->t_in = t2 - t0;
            prof->t_exec = t3 - t2;
            prof->t_out = t5 - t3;
            prof->bytes_in = (double)n_in;
            prof->bytes_out = (double)nb * nch + 8;
        }
        return 1;
    }
    std::vector<float> h_out(nP * nch);
    if (axclrtMemcpy(h_out.data(), d_out.p, nP * 4 * nch, AXCL_MEMCPY_DEVICE_TO_HOST)) {
        fprintf(stderr, "sdr_acc_axcl: memcpy error\n");
        return 0;
    }
    double t4 = now();
    for (int k = 0; k < K; k++) {
        const float *o = h_out.data() + (size_t)(k / Kc) * nP + (size_t)(k % Kc) * R * B;
        float *__restrict p = P + (size_t)k * ldP;
        for (int n = 0; n < nout; n++) p[n] += o[n] * sc;
    }
    double t5 = now();
    if (getenv("SDR_ACC_AXCL_DEBUG")) {
        fprintf(stderr, "sdr_acc_axcl: M=%d Kc=%d R=%d nw=%d K=%d NW=%d nch=%d prep %.2f "
            "in %.2f exec %.2f out %.2f acc %.2f ms\n", M, Kc, R, nw, K, NW, nch, (t1 - t0) * 1e3,
            (t2 - t1) * 1e3, (t3 - t2) * 1e3, (t4 - t3) * 1e3, (t5 - t4) * 1e3);
    }
    if (prof) {
        prof->t_in = t2 - t0;
        prof->t_exec = t3 - t2;
        prof->t_out = t5 - t3;
        prof->bytes_in = (double)n_in;
        prof->bytes_out = (double)nP * 4 * nch;
    }
    return 1;
}

// parallel code search (plugin interface) ------------------------------------
static int acc_search_code(const int8_t *x, const float *code, int M, double fs,
    const double *fc, int K, int nout, float *P, int ldP, sdr_acc_prof_t *prof)
{
    return search_multi(&x, 1, code, M, fs, fc, K, nout, P, ldP, NULL, NULL, prof);
}

static int acc_search_code_multi(const int8_t **x, int NW, const float *code,
    int M, double fs, const double *fc, int K, int nout, float *P, int ldP,
    sdr_acc_prof_t *prof)
{
    return search_multi(x, NW, code, M, fs, fc, K, nout, P, ldP, NULL, NULL, prof);
}

static int acc_search_code_peak(const int8_t **x, int NW, const float *code,
    int M, double fs, const double *fc, int K, int nout, float *Pk, int *ix,
    sdr_acc_prof_t *prof)
{
    return search_multi(x, NW, code, M, fs, fc, K, nout, NULL, 0, Pk, ix, prof);
}

// initialize / finalize -------------------------------------------------------
static int acc_init(const char *opt)
{
    model_dir.clear();
    std::string s = opt ? opt : "";
    for (size_t p = 0; p < s.size(); ) {
        size_t q = s.find(',', p);
        std::string t = s.substr(p, q == std::string::npos ? q : q - p);
        if (t.compare(0, 6, "model=") == 0) model_dir = t.substr(6);
        else if (!t.empty()) fprintf(stderr, "sdr_acc_axcl: unknown option %s\n",
            t.c_str());
        if (q == std::string::npos) break;
        p = q + 1;
    }
    const char *env;
    if (model_dir.empty() && (env = getenv("SDR_ACC_AXCL_MODEL"))) model_dir = env;
    if (model_dir.empty()) { // <plugin dir>/axcl
        Dl_info info;
        if (dladdr((void *)acc_init, &info) && info.dli_fname) {
            std::string f = info.dli_fname;
            size_t i = f.find_last_of('/');
            model_dir = (i == std::string::npos ? std::string(".") : f.substr(0, i)) + "/axcl";
        }
    }
    mfiles.clear();
    if (DIR *dp = opendir(model_dir.c_str())) {
        while (struct dirent *e = readdir(dp)) {
            int M, Kc, R, nw = 1, red, len = (int)strlen(e->d_name);
            const char *suf = strstr(e->d_name, "_hs");
            if (sscanf(e->d_name, "acq_M%d_K%d_R%d_hs", &M, &Kc, &R) != 3 || !suf) continue;
            std::string t = suf + 3;
            if (t.size() < 8 || t.compare(t.size() - 8, 8, ".axmodel")) continue;
            t = t.substr(0, t.size() - 8);
            if ((red = t.size() >= 4 && !t.compare(t.size() - 4, 4, "_red"))) t = t.substr(0, t.size() - 4);
            if (!t.empty() && sscanf(t.c_str(), "_w%d", &nw) != 1) continue;
            (void)len;
            mfiles.push_back({M, Kc, R, nw, red});
        }
        closedir(dp);
        std::sort(mfiles.begin(), mfiles.end());
    }
    axclrtDeviceList dl;
    if (axclInit(AXCL_CONF) || axclrtGetDeviceList(&dl) || dl.num < 1 ||
        axclrtSetDevice(dl.devices[0]) ||
        axclrtCreateContext(&dctx, dl.devices[0]) ||
        axclrtEngineInit(AXCL_VNPU_DISABLE)) {
        fprintf(stderr, "sdr_acc_axcl: no Axera device\n");
        return 0;
    }
    dev_id = dl.devices[0];

    // load all models (the execution times measured) at the initialization
    for (auto &f : mfiles) get_model(f[0], f[1], f[2], f[3], f[4]);
    return 1;
}

static void acc_exit(void)
{
    if (dev_id < 0) return;
    axclrtSetCurrentContext(dctx);
    for (auto &p : amodels) {
        amodel_t *m = p.second.get();
        if (!m) continue;
        if (m->io) axclrtEngineDestroyIO(m->io);
        if (m->info) axclrtEngineDestroyIOInfo(m->info);
        if (m->id) axclrtEngineUnload(m->id);
    }
    amodels.clear();
    d_in.free_(); d_acc[0].free_(); d_acc[1].free_(); d_zero.free_(); d_out.free_();
    d_red.free_(); d_redt.free_();
    for (auto &p : fplans) fftwf_destroy_plan(p.second);
    fplans.clear();
    axclrtEngineFinalize();
    axclrtDestroyContext(dctx);
    axclrtResetDevice(dev_id);
    axclFinalize();
    dev_id = -1;
}

static const sdr_acc_plugin_t plugin = {
    SDR_ACC_API_VER, "axcl", acc_init, acc_exit, acc_search_code,
    acc_search_code_multi, acc_search_code_peak
};

extern "C" const sdr_acc_plugin_t *sdr_acc_plugin(void)
{
    return &plugin;
}
